for(const job of jobs){const local=vaJobs[job.id];if(!local)continue;const original=[job.name,job.summary,job.tasks,job.skills,job.routes,job.place,job.first,job.watch,job.starter];for(let i=0;i<original.length;i++){const left=original[i],right=local[i];if(Array.isArray(left))left.forEach((value,index)=>{if(right[index])vaText[value]=right[index]});else if(right)vaText[left]=right}}
let language=localStorage.getItem(languageKey)==='va'?'va':'es';
const tr=value=>language==='va'?(vaText[String(value)]??String(value)):String(value);
function dynamicVa(value){if(vaText[value])return vaText[value];let match=value.match(/^Ver (\d+) profesiones( ↗)?$/);if(match)return `Veure ${match[1]} professions${match[2]||''}`;match=value.match(/^(\d+) profesiones$/);if(match)return `${match[1]} professions`;match=value.match(/^(\d+) profesión$/);if(match)return `${match[1]} professió`;match=value.match(/^Ver ficha de (.+)$/);if(match)return `Veure fitxa ${/^[aeiouàèéíòóú]/i.test(tr(match[1]))?'d’':'de '}${tr(match[1])}`;match=value.match(/^(Añadir|Quitar) (.+) (a|de) la comparación$/);if(match)return `${match[1]==='Añadir'?'Afegir':'Llevar'} ${tr(match[2])} ${match[3]==='a'?'a':'de'} la comparació`;match=value.match(/^Quitar (.+)$/);if(match)return `Llevar ${tr(match[1])}`;match=value.match(/^Empieza por: (.+)$/);if(match)return `Comença per: ${tr(match[1])}`;match=value.match(/^(.+) · FICHA ORIENTATIVA$/);if(match)return `${tr(match[1])} · FITXA ORIENTATIVA`;match=value.match(/^Progreso: (.+)$/);if(match)return `Progrés: ${match[1]}`;return null}
function translatePage(){document.documentElement.lang=language==='va'?'ca-ES-valencia':'es';document.querySelectorAll('[data-language]').forEach(select=>{select.value=language;select.setAttribute('aria-label','Idioma de la web')});const reverse=Object.fromEntries(Object.entries(vaText).map(([es,va])=>[va,es]));const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement?.closest('script,style'))continue;if(language==='es'&&!node.parentElement?.closest('header,footer'))continue;const original=node.nodeValue;const trimmed=original.trim();if(!trimmed)continue;const translated=language==='va'?(dynamicVa(trimmed)??trimmed):reverse[trimmed];if(translated&&translated!==trimmed)node.nodeValue=original.replace(trimmed,translated)}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(element=>{for(const name of ['placeholder','aria-label','title']){const value=element.getAttribute(name);const translated=language==='va'?(value&&dynamicVa(value)):reverse[value];if(value&&translated)element.setAttribute(name,translated)}})}
function translateMeta(){const meta=document.querySelector('meta[name="description"]');if(!meta)return;if(!meta.dataset.es)meta.dataset.es=meta.content;meta.content=language==='va'?(vaText[meta.dataset.es]||meta.dataset.es):meta.dataset.es}
